testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { rotaDaVersao, erroDeContrato, quebraCompatibilidade } from './solution.mjs';

test('rotaDaVersao monta o caminho versionado', () => {
  assert.equal(rotaDaVersao(1, 'pedidos'), '/v1/pedidos');
  assert.equal(rotaDaVersao(2, 'pedidos'), '/v2/pedidos');
});

test('rotaDaVersao lança com versão inválida', () => {
  assert.throws(() => rotaDaVersao(0, 'pedidos'));
  assert.throws(() => rotaDaVersao(-1, 'pedidos'));
  assert.throws(() => rotaDaVersao(2.5, 'pedidos'));
});

test('erroDeContrato devolve o envelope de erro padrão', () => {
  assert.deepEqual(erroDeContrato('nao_encontrado', 'recurso não existe'), {
    error: { code: 'nao_encontrado', message: 'recurso não existe' }
  });
});

test('quebraCompatibilidade separa mudanças que quebram das aditivas', () => {
  assert.equal(quebraCompatibilidade({ tipo: 'remover_campo' }), true);
  assert.equal(quebraCompatibilidade({ tipo: 'renomear_campo' }), true);
  assert.equal(quebraCompatibilidade({ tipo: 'mudar_tipo' }), true);
  assert.equal(quebraCompatibilidade({ tipo: 'adicionar_campo' }), false);
  assert.equal(quebraCompatibilidade({ tipo: 'novo_endpoint' }), false);
  assert.equal(quebraCompatibilidade({ tipo: 'misterioso' }), true);
});

solutionCode:
export function rotaDaVersao(versao, recurso) {
  if (!Number.isInteger(versao) || versao <= 0) {
    throw new Error('versão inválida: número inteiro positivo');
  }
  return `/v${versao}/${recurso}`;
}

export function erroDeContrato(code, message) {
  return { error: { code, message } };
}

export function quebraCompatibilidade(mudanca) {
  // sem objeto de mudança não dá para saber: trate como quebra
  if (mudanca === null || mudanca === undefined) {
    return true;
  }
  // mudanças aditivas não quebram; qualquer outra é tratada como quebra
  if (mudanca.tipo === 'adicionar_campo' || mudanca.tipo === 'novo_endpoint') {
    return false;
  }
  return true;
}
